#!/usr/bin/env python3
# THE NUMBERS WALK sitting 7 — BALAK (2026-09-11): THE CLAIMS of Numbers 22:1-25:19, four manifests (one per draft unit), read off the
# four ledgers of this sitting, every claim LABELED (World/step9/CLAIM_LABELS.md's vocabulary), a machine check where the ink allows —
# every he_contains substring CUT FROM THE SNAPSHOT STORE'S OWN BYTES by the word's CONSONANTS (sitting 6's form). Claim IDs per unit:
# BK22A (the call and the ass), BK23A (the first two oracles), BK24A (the last two), BK25A (Peor and Phinehas). Written once (the files
# must not exist; the ID prefixes checked absent from every existing manifest and unit). Every source cite is checked against its
# ledger's CITE INDEX before a byte is written.
import json, os, re, sqlite3, glob
ROOT = '<repo-old>'
DATE = '2026-09-11'
UNITS = {'num_22_balak_bilam_call': 'BK22A', 'num_23_oracles_1_2': 'BK23A', 'num_24_oracles_3_4': 'BK24A', 'num_25_peor_pinchas': 'BK25A'}
OUT = {u: f'{ROOT}/logic/oral_audit/manifests/{u}_claims.json' for u in UNITS}
for o in OUT.values(): assert not os.path.exists(o), o
for pre in UNITS.values():   # the claim-ID ceiling: the prefix must be new in BOTH strata
    for f in glob.glob(f'{ROOT}/logic/oral_audit/manifests/*_claims.json') + glob.glob(f'{ROOT}/logic/units/*.yaml'):
        assert f'{pre}-' not in open(f, encoding='utf-8').read(), (pre, f)
CI = {}
for u in UNITS:
    led = open(f'{ROOT}/logic/oral_triage/{u}_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
    CI[u] = set(re.findall(r'^(Sifrei Bamidbar \d+:\d+|Onkelos Num \d+:\d+)$', led, re.M))
assert sum(len(v) for v in CI.values()) == 120, {u: len(v) for u, v in CI.items()}
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, n, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth and (len(hit) == 1 or nth is not None), (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    n = min(len(piece), max(n, 6))
    assert n >= 6, (book, ch, v, word, piece)
    return idx, piece[:n]
def hc(ref, word, n, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, n, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
def onk(c, lo, hi): return '; '.join(f'Onkelos Num {c}:{v}' for v in range(lo, hi + 1))
def sif(*rows): return '; '.join(f'Sifrei Bamidbar {r}' for r in rows)

