n_claims = sum(len(v) for v in C.values())
assert n_claims == 40, n_claims
for u, claims in C.items():
    for c in claims:
        assert c['id'].startswith(UNITS[u]) and c['middah'] and c['check']['contains'], c['id']
        for s in c['source'].split('; '): assert s in CI[u], (c['id'], s)
    json.dump(claims, open(OUT[u], 'w', encoding='utf-8'), ensure_ascii=False, indent=1); open(OUT[u], 'a', encoding='utf-8').write('\n')
    print(f'{u}: {len(claims)} claims -> {OUT[u]}')
print(f'BALAK: {n_claims} claims across {len(C)} manifests')
